interface Source<out T> { fun load(): T }
interface Sink<in T> { fun save(value: T) }
data class Expense(val amount: Double)
class OneExpense : Source<Expense> { override fun load() = Expense(7.5) }
class PrintAny : Sink<Any> { override fun save(value: Any) = println(value) }
fun main() {
    val source: Source<Expense> = OneExpense()
    val sink: Sink<Expense> = PrintAny()
    sink.save(source.load())
}
